def transform(grid):
    # No candidate reproduced all received demonstrations, so retain the
    # original task program unchanged as required.
    r = next(i for i, row in enumerate(grid) if len(set(row)) == 1)
    top, bottom = grid[:r], grid[r + 1:]
    counts = {}
    for row in bottom:
        for x in row:
            counts[x] = counts.get(x, 0) + 1
    bg = max(counts, key=counts.get)
    fg = next(x for x in counts if x != bg)
    top_counts = {}
    for row in top:
        for x in row:
            top_counts[x] = top_counts.get(x, 0) + 1
    top_bg = max(top_counts, key=top_counts.get)
    return [[top_bg if x == fg else 3 for x in row] for row in bottom]

